 fields.et4420.push(['decimal','Ondalıklı gösterge','off',['off:Tam sayı','on:0.1° çözünürlük']],['functionKey','F.key · Ön tuş işlevi','off',['off:Kapalı','second:İkinci ayar','manual:Elle güç','tune:Otomatik ayar']],...([1,2].flatMap(n=>[['a'+n+'Low','A'+n+'.S.Lo · Alarm alt sınırı',0,-200,1700,.1],['a'+n+'High','A'+n+'.S.Hi · Alarm üst sınırı',600,-200,1700,.1]])),['a1Pb','A1.Pb · Soğutma oransal bant (%)',0,0,100,.1],['a1Ti','A1.t.i · Soğutma integral (dk)',0,0,100,.1],['a1Td','A1.t.d · Soğutma türev (dk)',0,0,25,.01],['a1Cycle','A1.Ct · Soğutma çevrimi (sn)',20,1,125,1],['a1Bias','A1.PS · Soğutma ofseti (%)',0,0,100,.1],['a1ErrorPower','A1.EP · Hata gücü (%)',0,0,100,.1],['securityCode','S.Cod · Menü erişim kodu',0,0,999,1],...['control','alarm1','alarm2','config','tune'].map((k,i)=>['lock_'+k,['Co.Sc','A1.Sc','A2.Sc','Con.Sc','St.Sc'][i]+' · Menü erişimi','yes',['yes:Değiştirilebilir','no:Yalnız okunabilir','none:Gizli']]));
