  const rows=fields[d.instrument];if(!rows)return d.id==='thermocouple'?`<label>Termokupl tipi<select data-thermal-param="thermocoupleType">${types.map(t=>`<option ${(c.thermocoupleType||'K')===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Soğuk uç sıcaklığı (°C)<input type="number" min="0" max="100" step="0.1" data-thermal-param="coldJunction" value="${esc(c.coldJunction??25)}"></label>`:'';
  return `<details open><summary>${esc(d.model)}</summary><p class="field-note">${esc(notes[d.instrument])}</p>${rows.map(([k,label,f,a,b,step])=>{const value=I.cfg(c,k,f),controller=d.instrument==='et4420',security=k==='securityCode'||k.startsWith('lock_');if(controller&&!security&&I.cfg(c,'lock_'+group(k),'yes')==='none')return '';const disabled=controller&&!editable(c,k)?'disabled':'';return `<label>${esc(label)}${Array.isArray(a)?`<select data-instrument-param="${k}" ${disabled}>${a.map(o=>{const [v,l]=o.split(':');return `<option value="${esc(v)}" ${d.instrument==='et4420'&&k==='input'&&v==='L'?'disabled':''} ${value===v?'selected':''}>${esc(l||v)}</option>`}).join('')}</select>`:`<input data-instrument-param="${k}" ${disabled} type="number" min="${a}" max="${b}" step="${step}" value="${esc(value)}">`}</label>`}).join('')}${d.instrument==='et4420'?'<p class="field-note">Menü erişimini değiştirmek için S.Cod: 442. Fabrika ayarı için S.Cod: 0. Otomatik ayar, bağlı sensörün değişen proses cevabını bekler.</p><button type="button" data-instrument-action="tune">Otomatik ayarı başlat / durdur</button><button type="button" data-instrument-action="reset">Fabrika ayarları</button>':''}</details>`;
