 function readout(d,c){
  if(!d.instrument)return '';const s=c._instrument,q=c._controller,lines=[];
  if(!s)lines.push('Simülasyon bekliyor');else if(d.instrument==='ht2')lines.push(`${s.temperature??'—'} °C / ${s.humidity??'—'} %RH`,s.t?`T: ${s.t.value.toFixed(2)} ${s.t.unit} · RH: ${s.rh.value.toFixed(2)} ${s.rh.unit}`:'');
  else if(d.instrument==='et4420'){if(q?.on)lines.push(`PV ${Number.isFinite(q.pv)?q.pv.toFixed(1):'—'} °C · SV ${q.sp} °C`,`Çıkış: ${(q.power||0).toFixed(1)} %`)}
  else{if(s.temperature!==undefined)lines.push(`${s.model||d.model} · ${I.cfg(c,'input','PT100')} · ${s.temperature.toFixed(1)} °C`);if(s.input!==undefined&&s.input!==null)lines.push(`Giriş: ${s.input.toFixed(3)} ${d.instrument==='tx11'?'mV':'V'}`);if(s.weight!==undefined)lines.push(`${s.weight.toFixed(2)} kg`);if(s.output)lines.push(`Çıkış: ${s.output.value.toFixed(3)} ${s.output.unit}`);if(s.outputPins)lines.push('Ölçüm uçları: '+s.outputPins[0]+' (+) / '+s.outputPins[1]+' (−)')}
  if(q?.error||s?.error)lines.push(q?.error||s.error);if(s?.loadWarning)lines.push(s.loadWarning);if(q?.tune)lines.push(q.tune);
  return `<g data-instrument-readout="1"><rect x="${d.w/2-115}" y="${d.h+42}" width="230" height="${Math.max(1,lines.length)*18+10}" rx="4" fill="#edf6fa" stroke="#7c9aab"/>${lines.map((l,i)=>`<text x="${d.w/2}" y="${d.h+59+i*18}" text-anchor="middle" font-size="10" fill="#204858" stroke="none">${esc(l)}</text>`).join('')}</g>`;
 }
